{"action":"run_python","research_note":"Compute discrete Fourier growth rates for the candidate regime F=0.0720,k=0.0620, ratio Du/Dv=3 on the L=40 periodic domain, and confirm that scaling absolute diffusivities by s=10 removes all unstable discrete modes. This supplies the quantitative prediction to be tested by nonlinear simulation.","active_claim_id":"claim_root","argv":["python","-c","import numpy as np, json
F=0.072; k=0.062; L=40.0
# HSS lower branch
u=(1-np.sqrt(1-4*(F+k)**2/F))/2; v=(F+k)/u
print('u,v',u,v)
fu=-F-v*v; fv=-2*u*v; gu=v*v; gv=2*u*v-(F+k)
print('jac',fu,fv,gu,gv,'tr',fu+gv,'det',fu*gv-fv*gu)
def lam(q,Du,Dv):
 A=fu-Du*q*q; B=gv-Dv*q*q; tr=A+B; det=A*B-fv*gu; return tr/2+np.sqrt(max(tr*tr-4*det,0))/2
for s in [0.1,1.0,10.0]:
 Du=s; Dv=s/3.0
 print('\ns',s,'Du,Dv',Du,Dv)
 for n in range(0,9):
  q=2*np.pi*n/L
  if n==0: print(' homogeneous q0 lam',lam(q,Du,Dv))
  else: print(' n',n,'q',round(q,5),'lam',round(lam(q,Du,Dv),6))
